extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var default_filter = ProjectSettings.get_setting("rendering/textures/canvas_textures/default_texture_filter")
	if not check("setting", default_filter == 0, "Il filtro predefinito del progetto deve essere Nearest (0)"):
		return
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena main.tscn deve caricarsi correttamente"):
		return
	var player := find_by_name(main, "Player") as Sprite2D
	if not check("player", player != null, "Nella scena deve esserci il nodo Player"):
		return
	check("player_filter", player.texture_filter == CanvasItem.TEXTURE_FILTER_PARENT_NODE or player.texture_filter == CanvasItem.TEXTURE_FILTER_NEAREST, "Lo sprite Player deve mantenere una resa nitida (Inherit o Nearest)")
	var coin := find_by_name(main, "Coin") as Sprite2D
	if not check("coin", coin != null, "Nella scena deve esserci il nodo Coin"):
		return
	check("coin_filter", coin.texture_filter == CanvasItem.TEXTURE_FILTER_PARENT_NODE or coin.texture_filter == CanvasItem.TEXTURE_FILTER_NEAREST, "Lo sprite Coin deve mantenere una resa nitida (Inherit o Nearest)")
	var emblem := find_by_name(main, "Emblem") as Sprite2D
	if not check("emblem", emblem != null, "Nella scena deve esserci il nodo Emblem"):
		return
	check("emblem_filter", emblem.texture_filter == CanvasItem.TEXTURE_FILTER_LINEAR, "Il nodo Emblem deve avere il filtro impostato esplicitamente su Linear (2)")
